package com.example.gtamusicplayer;

import android.Manifest;
import android.app.Activity;
import android.os.Bundle;
import android.os.Build;
import android.content.pm.PackageManager;
import android.database.Cursor;
import android.content.ContentUris;
import android.net.Uri;
import android.provider.MediaStore;
import android.media.MediaPlayer;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import java.util.*;

public class MainActivity extends Activity {
  final int BG=Color.rgb(8,11,16), PANEL=Color.rgb(17,24,32), NEON=Color.rgb(229,255,0), WHITE=Color.rgb(246,247,249), MUTED=Color.rgb(154,164,178);
  ArrayList<Track> tracks=new ArrayList<>(); Track current=null; MediaPlayer player; LinearLayout root, content; String page="welcome"; EditText searchBox;
  static class Track { long id,duration; String title,artist,album; Uri uri; Track(long i,String t,String a,String al,long d,Uri u){id=i;title=t;artist=a;album=al;duration=d;uri=u;} }
  @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);showWelcome();}
  GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(radius);return d;}
  TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
  LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
  LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
  void base(String title){page=title;root=column();root.setBackgroundColor(BG);setContentView(root);}
  void showWelcome(){base("welcome");root.setGravity(Gravity.CENTER);root.setPadding(26,28,26,28);TextView logo=text("grand theft\nauto",43,WHITE,true);logo.setGravity(Gravity.CENTER);root.addView(logo);TextView sub=text("MUSIC PLAYER",27,NEON,true);sub.setGravity(Gravity.CENTER);root.addView(sub);Space sp=new Space(this);root.addView(sp,new LinearLayout.LayoutParams(1,35));TextView welcome=text("欢迎回来\n\n本地音乐，随时随地。",18,WHITE,true);welcome.setGravity(Gravity.CENTER);root.addView(welcome);Space sp2=new Space(this);root.addView(sp2,new LinearLayout.LayoutParams(1,28));Button start=new Button(this);start.setText("开始使用");start.setTextColor(BG);start.setBackgroundTintList(android.content.res.ColorStateList.valueOf(NEON));root.addView(start,new LinearLayout.LayoutParams(-1,58));start.setOnClickListener(v->requestAudioPermission());TextView note=text("SIMPLE & CLEAN  •  PLAY YOUR STYLE",12,MUTED,false);note.setGravity(Gravity.CENTER);root.addView(note);}
  void requestAudioPermission(){String p=Build.VERSION.SDK_INT>=33?Manifest.permission.READ_MEDIA_AUDIO:Manifest.permission.READ_EXTERNAL_STORAGE;if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(p)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{p},9);else{scan();showHome();}}
  @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==9&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED){scan();showHome();}else{showHome();}}
  void scan(){tracks.clear();Uri collection=MediaStore.Audio.Media.EXTERNAL_CONTENT_URI;String[] proj={MediaStore.Audio.Media._ID,MediaStore.Audio.Media.TITLE,MediaStore.Audio.Media.ARTIST,MediaStore.Audio.Media.ALBUM,MediaStore.Audio.Media.DURATION};try(Cursor c=getContentResolver().query(collection,proj,MediaStore.Audio.Media.IS_MUSIC+" != 0",null,MediaStore.Audio.Media.TITLE+" COLLATE NOCASE ASC")){if(c!=null)while(c.moveToNext()){long id=c.getLong(0);String title=c.getString(1);String artist=c.getString(2);String album=c.getString(3);long dur=c.getLong(4);if(artist==null||artist.equals("<unknown>"))artist="未知艺术家";tracks.add(new Track(id,title==null?"未知歌曲":title,artist,album==null?"本地音乐":album,dur,ContentUris.withAppendedId(collection,id)));}}catch(Exception ignored){}}
  void header(String title,String action,Runnable run){LinearLayout r=row();r.setPadding(18,16,18,14);TextView t=text(title,23,WHITE,true);r.addView(t,new LinearLayout.LayoutParams(0,-2,1));TextView a=text(action,14,NEON,true);r.addView(a);a.setOnClickListener(v->run.run());root.addView(r);}
  void showHome(){base("home");header("GTA MUSIC","⟳ 刷新",()->{scan();showHome();});TextView banner=text("MY MUSIC!\n我的音乐 · 本地收藏\nPLAY YOUR STYLE",26,NEON,true);banner.setGravity(Gravity.CENTER_VERTICAL);banner.setPadding(22,12,12,12);banner.setBackground(shape(Color.rgb(28,42,55),20));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,150);bp.setMargins(16,4,16,12);root.addView(banner,bp);
    LinearLayout stats=row();stats.setPadding(12,5,12,12);String[] labels={"♫\n全部歌曲\n"+tracks.size()+" 首","◉\n专辑\n本地音乐","♧\n艺术家\n已扫描"};for(String s:labels){TextView c=text(s,14,WHITE,true);c.setGravity(Gravity.CENTER);c.setPadding(8,14,8,14);c.setBackground(shape(PANEL,14));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.setMargins(4,0,4,0);stats.addView(c,cp);c.setOnClickListener(v->showAll());}root.addView(stats);
    TextView recent=text("最近播放                                      更多 ›",18,WHITE,true);recent.setPadding(20,14,10,8);root.addView(recent);recent.setOnClickListener(v->showAll());ScrollView scroll=new ScrollView(this);LinearLayout list=column();for(int i=0;i<Math.min(tracks.size(),30);i++)list.addView(trackRow(tracks.get(i)));if(tracks.isEmpty()){TextView empty=text("还没有找到本地歌曲\n\n请将音乐文件保存到手机，再点击右上角刷新。",15,MUTED,false);empty.setGravity(Gravity.CENTER);empty.setPadding(20,35,20,35);list.addView(empty);}scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));bottomNav(0);}
  View trackRow(Track t){LinearLayout r=row();r.setPadding(16,10,14,10);TextView icon=text("♫",24,NEON,true);icon.setGravity(Gravity.CENTER);icon.setBackground(shape(Color.rgb(36,48,61),12));r.addView(icon,new LinearLayout.LayoutParams(48,48));LinearLayout details=column();details.setPadding(12,0,0,0);details.addView(text(t.title,15,WHITE,true));details.addView(text(t.artist+" · "+duration(t.duration),12,MUTED,false));r.addView(details,new LinearLayout.LayoutParams(0,-2,1));r.setOnClickListener(v->play(t));return r;}
  void showAll(){base("all");header("‹  全部歌曲","刷新",()->{scan();showAll();});TextView count=text(tracks.size()+" 首歌曲",13,MUTED,false);count.setPadding(18,0,0,8);root.addView(count);ScrollView s=new ScrollView(this);LinearLayout list=column();for(Track t:tracks)list.addView(trackRow(t));s.addView(list);root.addView(s,new LinearLayout.LayoutParams(-1,0,1));bottomNav(0);}
  void showSearch(){base("search");header("搜索音乐","⌂ 首页",()->showHome());searchBox=new EditText(this);searchBox.setSingleLine(true);searchBox.setHint("歌曲、艺术家或专辑");searchBox.setTextColor(WHITE);searchBox.setHintTextColor(MUTED);searchBox.setPadding(16,8,16,8);searchBox.setBackground(shape(PANEL,16));LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(-1,52);ep.setMargins(16,4,16,12);root.addView(searchBox,ep);LinearLayout results=column();ScrollView scroll=new ScrollView(this);scroll.addView(results);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));Runnable filter=()->{results.removeAllViews();String q=searchBox.getText().toString().toLowerCase(Locale.ROOT);for(Track t:tracks)if((t.title+" "+t.artist+" "+t.album).toLowerCase(Locale.ROOT).contains(q))results.addView(trackRow(t));};searchBox.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){filter.run();}public void afterTextChanged(android.text.Editable e){}});filter.run();bottomNav(1);}
  void showMine(){base("mine");header("我的","重新扫描",()->{scan();showMine();});TextView card=text("♫   本地音乐库\n\n      "+tracks.size()+" 首歌曲",19,WHITE,true);card.setPadding(22,24,18,24);card.setBackground(shape(PANEL,18));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(16,12,16,12);root.addView(card,p);TextView desc=text("支持系统音乐媒体库中的本地音频文件。",13,MUTED,false);desc.setPadding(18,8,18,8);root.addView(desc);bottomNav(2);}
  void bottomNav(int selected){LinearLayout nav=row();nav.setGravity(Gravity.CENTER);String[] labels={"⌂\n首页","⌕\n搜索","♙\n我的"};for(int i=0;i<3;i++){final int n=i;TextView t=text(labels[i],14,i==selected?NEON:MUTED,true);t.setGravity(Gravity.CENTER);t.setPadding(12,12,12,10);nav.addView(t,new LinearLayout.LayoutParams(0,-2,1));t.setOnClickListener(v->{if(n==0)showHome();else if(n==1)showSearch();else showMine();});}nav.setBackgroundColor(Color.rgb(12,17,23));root.addView(nav);}
  void play(Track t){current=t;try{if(player!=null){player.release();player=null;}player=new MediaPlayer();player.setDataSource(this,t.uri);player.setOnPreparedListener(mp->{mp.start();showPlayer();});player.setOnCompletionListener(mp->{if(current!=null){int i=tracks.indexOf(current);if(i>=0&&i<tracks.size()-1)play(tracks.get(i+1));}});player.prepareAsync();}catch(Exception e){Toast.makeText(this,"无法播放此音频",Toast.LENGTH_SHORT).show();}}
  void showPlayer(){base("player");header("‹   正在播放","•••",()->showHome());Space top=new Space(this);root.addView(top,new LinearLayout.LayoutParams(1,0,1));TextView art=text("♫",100,NEON,true);art.setGravity(Gravity.CENTER);art.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.rgb(28,56,80),Color.rgb(39,48,0),Color.rgb(16,21,29)}));LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,280);ap.setMargins(35,10,35,20);root.addView(art,ap);TextView title=text(current==null?"选择一首歌曲":current.title,23,WHITE,true);title.setGravity(Gravity.CENTER);root.addView(title);TextView artist=text(current==null?"GTA MUSIC PLAYER":current.artist,14,MUTED,false);artist.setGravity(Gravity.CENTER);root.addView(artist);SeekBar seek=new SeekBar(this);seek.setProgressTintList(android.content.res.ColorStateList.valueOf(NEON));seek.setThumbTintList(android.content.res.ColorStateList.valueOf(NEON));root.addView(seek);TextView times=text("0:00                                            "+(current==null?"0:00":duration(current.duration)),12,MUTED,false);root.addView(times);LinearLayout controls=row();controls.setGravity(Gravity.CENTER);TextView prev=text("|◀",28,WHITE,true),toggle=text("❚❚",34,NEON,true),next=text("▶|",28,WHITE,true);for(TextView c:new TextView[]{prev,toggle,next}){c.setGravity(Gravity.CENTER);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,80,1);controls.addView(c,cp);}prev.setOnClickListener(v->{if(current!=null){int i=tracks.indexOf(current);if(i>0)play(tracks.get(i-1));}});next.setOnClickListener(v->{if(current!=null){int i=tracks.indexOf(current);if(i>=0&&i<tracks.size()-1)play(tracks.get(i+1));}});toggle.setOnClickListener(v->{if(player!=null){if(player.isPlaying()){player.pause();toggle.setText("▶");}else{player.start();toggle.setText("❚❚");}}});root.addView(controls);Space bottom=new Space(this);root.addView(bottom,new LinearLayout.LayoutParams(1,0,1));}
  String duration(long ms){long s=ms/1000;return String.format(Locale.getDefault(),"%d:%02d",s/60,s%60);}
  @Override protected void onDestroy(){if(player!=null){player.release();player=null;}super.onDestroy();}
}
